import React,{useEffect,useRef,useState} from 'react';
import {storyTrackKey,storyTrackReference} from '../../../domain/story-tracks.mjs';
import {storyTrackDropOrder,storyTrackRenameOperation,storyTrackPointerTarget} from './story-track-controls.mjs';
import {Modal} from '../../shared/preferences.tsx';

export function StoryTrackName({track,busy,onRename,onSettings,lane=false}){
 const [name,setName]=useState(track.name),[saving,setSaving]=useState(false),[error,setError]=useState('');const skip=useRef(false),lock=useRef(false);
 useEffect(()=>setName(track.name),[track.name]);
 const submit=async()=>{if(skip.current){skip.current=false;return;}const op=storyTrackRenameOperation(track,name);if(!op||busy||lock.current){if(!name.trim())setName(track.name);return;}lock.current=true;setSaving(true);setError('');try{if(!await onRename(op))setError('尚未保存，请重试');}catch{setError('尚未保存，请重试');}finally{lock.current=false;setSaving(false);}};
 return <span className={`sa-track-name ${lane?'sa-track-lane-name':''}`} data-track-control><i style={{background:track.color}}/><input aria-label={`轨道名称：${track.name}`} title="直接编辑轨道名称；Enter 保存，Esc 取消" maxLength={80} value={name} disabled={busy||saving} onChange={e=>setName(e.target.value)} onBlur={submit} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();e.currentTarget.blur();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();skip.current=true;setName(track.name);setError('');e.currentTarget.blur();}}}/>{onSettings&&<button type="button" aria-label={`设置轨道：${track.name}`} title="颜色与更多设置" disabled={busy} onClick={onSettings}>···</button>}{error&&<small role="alert">{error}<button disabled={saving||busy} onClick={submit}>重试</button></small>}</span>;
}

export function StoryTrackControls({catalog,placed,busy,mutate,onSettings,onCreate,controlRef,viewport}){
 const root=useRef(null),gesture=useRef(null),[drag,setDrag]=useState(null),[confirm,setConfirm]=useState(null),[saving,setSaving]=useState(false),[notice,setNotice]=useState('');
 const disabled=busy||saving;
 const cancel=()=>{gesture.current=null;setDrag(null);};
 useEffect(()=>{const key=e=>{if(e.key==='Escape')cancel();};window.addEventListener('blur',cancel);window.addEventListener('keydown',key);return()=>{window.removeEventListener('blur',cancel);window.removeEventListener('keydown',key);};},[]);
 useEffect(()=>{cancel();setConfirm(null);},[catalog.map(t=>t.key).join('|')]);
 useEffect(()=>{if(busy)cancel();},[busy]);
 const run=async(op,message)=>{setSaving(true);setNotice('');try{const ok=await mutate(op,message);if(!ok)setNotice('尚未保存，请核对待确认请求后重试。');return ok;}catch{setNotice('尚未保存，请重试。');return false;}finally{setSaving(false);}};
 const finish=g=>{cancel();if(!g||disabled)return;if(g.side){setConfirm({key:g.key,side:g.side});return;}const order=storyTrackDropOrder(catalog,g.key,g.target,g.after);if(order)void run({type:'track.reorder',mode:'story',order},'已调整故事轨道顺序；日期与叙述顺序不变。');};
 const move=e=>{const g=gesture.current;if(!g||g.pointerId!==e.pointerId)return;if(!g.moved&&Math.hypot(e.clientX-g.x,e.clientY-g.y)<6)return;e.preventDefault();g.moved=true;Object.assign(g,storyTrackPointerTarget(root.current,viewport.current,catalog,g,e.clientX,e.clientY));setDrag({...g});};
 const endPointer=e=>{const g=gesture.current;if(g?.pointerId!==e.pointerId)return;move(e);if(g.moved)finish(g);else cancel();};
 const keyboard=(e,key)=>{if(disabled)return;if(e.key==='Escape'){e.preventDefault();cancel();return;}if(!drag&&[' ','Enter'].includes(e.key)){e.preventDefault();setDrag({key,keyboard:true,target:key,after:false});return;}if(!drag?.keyboard||drag.key!==key)return;if([' ','Enter'].includes(e.key)){e.preventDefault();finish(drag);}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const delta=['ArrowLeft','ArrowUp'].includes(e.key)?-1:1,at=catalog.findIndex(t=>t.key===(drag.target||key)),next=Math.max(0,Math.min(catalog.length-1,at+delta));setDrag({...drag,target:catalog[next].key,after:delta>0});}};
 const handlers={begin:(e,key)=>{if(e.button!==0||disabled)return;e.preventDefault();e.stopPropagation();gesture.current={key,pointerId:e.pointerId,x:e.clientX,y:e.clientY,moved:false,originSide:e.currentTarget.closest('[data-story-space]')?.dataset.storySpace};e.currentTarget.setPointerCapture(e.pointerId);},move,end:endPointer,cancel,keyboard};
 useEffect(()=>{controlRef.current=handlers;return()=>{controlRef.current=null;};});
 useEffect(()=>{const el=viewport.current;if(!el)return;for(const lane of el.querySelectorAll('[data-story-track]')){lane.classList.toggle('sa-track-drop-before',drag?.target===lane.dataset.storyTrack&&!drag.after&&drag.key!==drag.target);lane.classList.toggle('sa-track-drop-after',drag?.target===lane.dataset.storyTrack&&drag.after&&drag.key!==drag.target);}return()=>{for(const lane of el.querySelectorAll('[data-story-track]'))lane.classList.remove('sa-track-drop-before','sa-track-drop-after');};},[drag,viewport]);
 const track=confirm&&catalog.find(t=>t.key===confirm.key),affected=track?placed.filter(c=>storyTrackKey(c.time.story)===track.key).length:0;
 return <section className="sa-track-controls" aria-label="故事轨道" ref={root} data-track-control><style>{styles}</style><details><summary><strong>故事轨道</strong><span className="sa-track-summary-hint">点名称改名 · 拖动排序</span><small>{catalog.length} 条</small></summary><header><button disabled={disabled} onClick={onCreate}>＋ 新建轨道</button></header><div className="sa-track-direct-list">{catalog.map(t=><div key={t.key} data-track-row={t.key} className={`sa-track-direct-row ${drag?.key===t.key?'is-dragging':''} ${drag?.target===t.key&&drag.key!==t.key?(drag.after?'drop-after':'drop-before'):''}`}><button className="sa-track-grip" aria-label={`拖动轨道：${t.name}`} aria-pressed={drag?.key===t.key} title="拖动排序；键盘空格拾起，方向键移动，Enter 放下，Esc 取消" disabled={disabled} onPointerDown={e=>{if(e.button!==0||disabled)return;e.preventDefault();e.stopPropagation();gesture.current={key:t.key,pointerId:e.pointerId,x:e.clientX,y:e.clientY,moved:false};e.currentTarget.setPointerCapture(e.pointerId);}} onPointerMove={move} onPointerUp={endPointer} onPointerCancel={cancel} onLostPointerCapture={()=>{if(gesture.current)cancel();}} onKeyDown={e=>keyboard(e,t.key)}>⠿</button><StoryTrackName track={t} busy={disabled} onRename={op=>run(op,'已保存轨道名称。')} onSettings={()=>onSettings(t)}/><small>{placed.filter(c=>storyTrackKey(c.time.story)===t.key).length} 张</small><button className="sa-track-side" disabled={disabled} title="整条轨道移动到另一侧，确认后生效" onClick={()=>setConfirm({key:t.key,side:t.side==='above'?'below':'above'})}>{t.side==='above'?'轴上':'轴下'} ⇅</button></div>)}{!catalog.length&&<p>还没有轨道，添加一个名字来整理事件；不限定主线或支线。</p>}</div></details>{drag&&<div className="sa-track-drop-zones">{[['above','轴上'],['below','轴下']].map(([side,label])=><div key={side} data-track-side-drop={side} className={drag.side===side?'active':''}>拖到{label} · 整条轨道</div>)}</div>}{(drag||notice)&&<p className="sa-track-help" role="status">{drag?(drag.side?`松手后确认整条轨道移到${drag.side==='above'?'轴上':'轴下'}；日期不变`:'移动到轨道间放下以排序；Esc 取消。键盘方向键移动，Enter 放下。'):(notice||'名称和颜色共享；这里排序独立，事件日期不变。空轨道也可直接命名。')}</p>}{track&&<Modal title="移动整条故事轨道" close={()=>{if(!saving)setConfirm(null);}}><div className="u-form"><p>将「{track.name}」的 {affected} 张已安排卡片移到时间轴{confirm.side==='above'?'上方':'下方'}，并设为新卡片的默认位置？</p><p>只改变上下摆放；日期、时长和叙述顺序保持不变。之后仍可单独移动卡片。</p><button disabled={disabled} onClick={async()=>{if(await run({type:'storyAxis.track.side',...storyTrackReference(track.key),side:confirm.side},'已移动整条轨道；日期与叙述顺序不变。'))setConfirm(null);}}>确认移动 {affected} 张卡片</button><button disabled={saving} onClick={()=>setConfirm(null)}>取消</button></div></Modal>}</section>;
}
export function StoryTrackLane({track,busy,onRename,onSettings,controlRef}){return <span className="sa-track-lane-head" data-track-control><button className="sa-track-grip" aria-label={`拖动轨道：${track.name}`} title="拖动整条轨道；空格拾起，方向键移动，Enter 放下，Esc 取消" disabled={busy} onPointerDown={e=>controlRef.current?.begin(e,track.key)} onPointerMove={e=>controlRef.current?.move(e)} onPointerUp={e=>controlRef.current?.end(e)} onPointerCancel={()=>controlRef.current?.cancel()} onLostPointerCapture={()=>controlRef.current?.cancel()} onKeyDown={e=>controlRef.current?.keyboard(e,track.key)}>⠿</button><StoryTrackName {...{track,busy,onRename,onSettings}}/></span>;}
const styles=`.sa-track-controls summary{cursor:pointer;font-size:11px;color:var(--cg-muted)}.sa-track-controls summary strong{font-size:12px;color:var(--cg-ink,#213b56);white-space:nowrap;flex:none}.sa-track-controls summary>small{white-space:nowrap;flex:none}.sa-track-summary-hint{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.sa-track-controls details[open] summary{margin-bottom:8px}.sa-track-lane-head{position:sticky;left:10px;z-index:6;display:inline-flex;align-items:center;background:var(--cg-paper,#fff);border:1px solid var(--cg-line,#d2dfed);border-radius:7px;height:26px}.sa-track-lane-head .sa-track-grip{font-size:16px;height:24px;padding:0 6px!important}.sa-lane.sa-track-drop-before{border-top:3px solid var(--cg-accent,#416b61)}.sa-lane.sa-track-drop-after{border-bottom:3px solid var(--cg-accent,#416b61)}.sa-track-controls{position:relative;margin:4px 0 8px;padding:6px 10px;border:1px solid var(--cg-line,#d2dfed);border-radius:12px;background:var(--cg-paper,#fff)}.sa-track-controls header{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:8px}.sa-track-controls header>strong{font-size:13px}.sa-track-controls header>span,.sa-track-help{font-size:11px;color:var(--cg-muted)}.sa-track-controls header>button{margin-left:auto}.sa-track-direct-list{display:flex;flex-wrap:wrap;gap:8px}.sa-track-direct-row{position:relative;display:flex;align-items:center;gap:5px;border:1px solid var(--cg-line,#d2dfed);border-radius:8px;padding:4px;background:var(--cg-panel,var(--cg-paper,#fff));max-width:100%;min-height:38px}.sa-track-direct-row.is-dragging{opacity:.65}.sa-track-direct-row.drop-before:before,.sa-track-direct-row.drop-after:after{content:'';position:absolute;top:-4px;bottom:-4px;width:3px;background:var(--cg-accent,#416b61);border-radius:3px}.sa-track-direct-row.drop-before:before{left:-6px}.sa-track-direct-row.drop-after:after{right:-6px}.sa-track-grip{touch-action:none;cursor:grab;font-size:20px;padding:4px 8px!important}.sa-track-grip:active{cursor:grabbing}.sa-track-name{display:inline-flex;align-items:center;gap:5px;position:relative;min-width:0}.sa-track-name>i{width:8px;height:8px;border-radius:50%;flex-shrink:0}.sa-track-name>input{width:110px;min-width:45px;max-width:100%;border:1px solid transparent!important;background:transparent!important;padding:4px!important;border-radius:4px;color:inherit;font-size:12px}.sa-track-name>input:hover,.sa-track-name>input:focus{border-color:var(--cg-line,#d2dfed)!important;background:var(--cg-paper,#fff)!important}.sa-track-name>small{position:absolute;top:100%;left:0;z-index:15;background:var(--cg-paper,#fff);padding:4px;white-space:nowrap}.sa-track-direct-row>small{font-size:10px;color:var(--cg-muted);white-space:nowrap}.sa-track-side{font-size:10px!important;white-space:nowrap}.sa-track-help{position:absolute;left:8px;right:8px;top:calc(100% + 2px);z-index:30;margin:0;padding:5px 8px;border-radius:6px;background:var(--cg-paper,#fff);pointer-events:none}.sa-track-drop-zones{position:absolute;left:4px;right:4px;top:0;z-index:30;background:var(--cg-paper,#fff);display:flex;gap:8px;margin-top:0}.sa-track-drop-zones>div{flex:1;border:1px dashed var(--cg-muted);border-radius:7px;padding:5px;text-align:center;font-size:12px}.sa-track-drop-zones>.active{background:var(--cg-accent-soft,#e3eee8);outline:2px solid var(--cg-accent,#416b61)}.sa-track-lane-name{position:sticky;left:10px;z-index:6;background:var(--cg-paper,#fff);border:1px solid var(--cg-line,#d2dfed);border-radius:7px;padding:1px 6px;max-width:230px}.sa-track-lane-name>input{width:130px}@media(max-width:600px){.sa-track-controls header>span{width:100%;order:3}.sa-track-direct-list{flex-wrap:nowrap;overflow-x:auto;padding:4px 6px}.sa-track-direct-row{flex-shrink:0}.sa-track-drop-zones>div{padding:5px}}`;
